async function change(action:CityCommand['action'],commandId:string=crypto.randomUUID(),expectedRevision?:number){
 const w=workspace,g=epoch,source=view;if(!w)throw new Error('Kampagne öffnen.');const id=action.kind==='create'?action.header.id:source?.header.id;if(!id)throw new Error('Stadt öffnen.');
 const command={commandId,token:w.token,campaignId:w.campaign.id,cityId:id,expectedRevision:action.kind==='create'?0:(expectedRevision??source!.header.revision),action};readRequest++;
 if(source?.demographics===null&&action.kind!=='create'){
  const receipt=await writeAtlasCommit({...command,action:{kind:action.kind==='undo'||action.kind==='redo'?action.kind:'city',...(action.kind==='undo'||action.kind==='redo'?{}:{command})} as import('./campaign-atlas-contracts').AtlasAction},pendingAtlasWrite(w.token)?.commandId===commandId);
  if(!receipt.ok){if(pendingAtlasWrite(w.token))throw new Error(receipt.error);throw new CityCommandRejected(receipt.error);}const ack=receipt.value;
  if(!owned(w.token,g)||view?.header.id!==source.header.id)throw new Error('Stadtkontext gewechselt.');
  try{await readCitySite(id,action.kind==='change'&&action.remove.includes(selected??'')?undefined:selected??undefined,w.token,g,++readRequest,true);}catch(error){siteReadRequired=true;tell('Stadt gespeichert. Element erneut laden: '+(error as Error).message,true);throw Object.assign(new Error('Gespeichert. Element vor weiterer Änderung neu laden.'),{committed:true,revision:ack.revision});}
  tell('Stadt gespeichert.');return view!;
 }
 const response=await atlasCityWrite(command);if(!owned(w.token,g)||view?.header.id!==source?.header.id)throw new Error('Stadtkontext gewechselt.');
 if(!response.ok){if(pendingAtlasWrite(w.token))throw new Error(response.error);throw new CityCommandRejected(response.error);}const result=response.value;readRequest++;view=result;preview=null;render();tell('Stadt gespeichert.');return result;
}
function unit(){return view?.units.find(u=>u.id===selected);}
function personDraft(u:CityUnit){if(u.kind!=='building'){people=null;return;}if(people?.unitId===u.id)return;people={moves:[],unitId:u.id,residents:new Set(u.residentIds??[]),workers:new Set(u.workerIds??[]),households:structuredClone(u.households??[]),jobs:structuredClone(u.jobs??[]),rows:new Map(knownPeople),visible:[],total:null};run(refreshPeople);}
async function relocateLifeRecord(role:'home'|'work',recordId:string){
 if(!await flushCity())return;const w=workspace,g=epoch,source=view,u=unit();if(!w||!source||u?.kind!=='building')return;
 const household=role==='home'?u.households?.find(h=>h.id===recordId):null,job=role==='work'?u.jobs?.find(j=>j.id===recordId):null,record=household??job;if(!record)throw new Error('Haushalt oder Beruf nicht mehr vorhanden.');
 const memberIds=household?.memberIds??job!.workerIds,title=(role==='home'?'Haushalt':'Beruf')+' „'+record.name+'“ umziehen';
 const destination=await chooseCityBuilding(w.token,title,u.id);if(!destination||!owned(w.token,g)||view?.header.id!==source.header.id)return;
 const targetView=unwrap(await window.campaign.city(w.token,destination.cityId));if(!owned(w.token,g)||view?.header.id!==source.header.id)return;const target=targetView.units.find(b=>b.id===destination.unitId&&b.kind==='building');if(!target)throw new Error('Zielhaus nicht mehr vorhanden.');
 const names=memberIds.map(id=>knownPeople.get(id)?.name??people?.rows.get(id)?.name??id);
 if(!await confirmCityLifeMove(title,(u.name||'Unbenanntes Haus')+' · '+source.header.name,destination.title+' · '+destination.cityTitle,names)||!owned(w.token,g)||view?.header.id!==source.header.id)return;
 const next=structuredClone(target);next.protected=true;if(household){next.households=[...(next.households??[]),structuredClone(household)];next.residentIds=[...new Set([...(next.residentIds??[]),...memberIds])];}else{next.jobs=[...(next.jobs??[]),structuredClone(job!)];next.workerIds=[...new Set([...(next.workerIds??[]),...memberIds])];}
 const result=await atlasCityWrite({commandId:crypto.randomUUID(),token:w.token,campaignId:w.campaign.id,cityId:destination.cityId,expectedRevision:targetView.header.revision,action:{kind:'change',upsert:[next],remove:[],label:role==='home'?'Haushalt umziehen':'Berufsgruppe umziehen',lifeMoves:[{role,recordId,fromCityId:source.header.id,fromUnitId:u.id,expectedRevision:source.header.revision,toUnitId:target.id}]}});unwrap(result);if(!owned(w.token,g))return;
 people=null;await openCityReference(destination.cityId,target.id);tell((role==='home'?'Haushalt':'Berufsgruppe')+' mit '+memberIds.length+' NSC umgezogen. Rückgängig ist in beiden beteiligten Städten verfügbar.');
}
const counted=(amount:number,one:string,many:string)=>amount+' '+(amount===1?one:many);
